PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS identity_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS identity_accounts(token_hash TEXT PRIMARY KEY,actor TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','reviewer','viewer')));
CREATE TABLE IF NOT EXISTS teacher_users(actor TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','teacher','reviewer')),status TEXT NOT NULL CHECK(status IN ('active','disabled')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,must_change_password INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS teacher_sessions(session_hash TEXT PRIMARY KEY,actor TEXT NOT NULL REFERENCES teacher_users(actor),created_at TEXT NOT NULL,expires_at TEXT NOT NULL,last_seen TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS teacher_sessions_actor ON teacher_sessions(actor,expires_at);
CREATE TABLE IF NOT EXISTS login_attempts(throttle_key TEXT PRIMARY KEY,fail_count INTEGER NOT NULL,window_started TEXT NOT NULL,locked_until TEXT);
CREATE TABLE IF NOT EXISTS registered_subjects(subject_id TEXT PRIMARY KEY,display_name BLOB,consent_record BLOB NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reference_images(reference_image_id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES registered_subjects(subject_id),image BLOB,feature BLOB,model_id TEXT,provenance TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reference_images_subject_status ON reference_images(subject_id,status,created_at);
CREATE TABLE IF NOT EXISTS video_authorizations(authorization_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,subject_id TEXT NOT NULL REFERENCES registered_subjects(subject_id),source_hash TEXT NOT NULL,consent_record BLOB NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS face_observations(face_id TEXT PRIMARY KEY,authorization_id TEXT NOT NULL REFERENCES video_authorizations(authorization_id),run_id TEXT NOT NULL,track_id INTEGER NOT NULL,frame_index INTEGER NOT NULL,global_time REAL NOT NULL,local_time REAL NOT NULL,bbox TEXT NOT NULL,image BLOB,feature BLOB,model_id TEXT NOT NULL,quality TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS identity_candidates(candidate_id TEXT PRIMARY KEY,subject_id TEXT REFERENCES registered_subjects(subject_id),run_id TEXT NOT NULL,track_id INTEGER NOT NULL,start REAL NOT NULL,end REAL NOT NULL,raw_similarity REAL,model_id TEXT,reference_image_id TEXT REFERENCES reference_images(reference_image_id),face_observation_ids TEXT NOT NULL,status TEXT NOT NULL,rejection_reason TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS identity_bindings(binding_id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES registered_subjects(subject_id),run_id TEXT NOT NULL,track_id INTEGER NOT NULL,clip_id TEXT NOT NULL,start REAL NOT NULL,end REAL NOT NULL,status TEXT NOT NULL,source_kind TEXT NOT NULL,evidence_refs TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL,continuity_status TEXT NOT NULL, CHECK(end>=start));
CREATE TABLE IF NOT EXISTS identity_review_history(review_id TEXT PRIMARY KEY,actor TEXT NOT NULL,operation TEXT NOT NULL,object_id TEXT NOT NULL,payload BLOB NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS classrooms(classroom_id TEXT PRIMARY KEY,owner_actor TEXT NOT NULL,name TEXT NOT NULL,grade TEXT NOT NULL DEFAULT '',term TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('active','archived')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS classrooms_owner ON classrooms(owner_actor,status,created_at);
CREATE TABLE IF NOT EXISTS classroom_students(classroom_id TEXT NOT NULL REFERENCES classrooms(classroom_id),subject_id TEXT NOT NULL REFERENCES registered_subjects(subject_id),status TEXT NOT NULL CHECK(status IN ('active','removed')),created_at TEXT NOT NULL,PRIMARY KEY(classroom_id,subject_id));
CREATE INDEX IF NOT EXISTS classroom_students_subject ON classroom_students(subject_id,status);
CREATE TABLE IF NOT EXISTS lesson_sessions(session_id TEXT PRIMARY KEY,classroom_id TEXT NOT NULL REFERENCES classrooms(classroom_id),title TEXT NOT NULL,scheduled_at TEXT,created_at TEXT NOT NULL,created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS classroom_videos(classroom_id TEXT NOT NULL REFERENCES classrooms(classroom_id),video_id TEXT NOT NULL,session_id TEXT REFERENCES lesson_sessions(session_id),created_at TEXT NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(classroom_id,video_id));
CREATE TABLE IF NOT EXISTS classroom_video_identity_scopes(video_id TEXT PRIMARY KEY,classroom_id TEXT NOT NULL REFERENCES classrooms(classroom_id),owner_actor TEXT NOT NULL,consent_record BLOB NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS identity_track_time ON identity_bindings(run_id,track_id,start,end,status);
CREATE INDEX IF NOT EXISTS identity_subject_time ON identity_bindings(subject_id,status,start);
CREATE INDEX IF NOT EXISTS identity_faces_time ON face_observations(run_id,track_id,global_time);
CREATE INDEX IF NOT EXISTS identity_history_object ON identity_review_history(object_id,created_at);
